use crate::types::RosterSummary;
use carbon_core::CarbonDeserialize;
use carbon_core::borsh;
use carbon_core::deserialize::CarbonDeserialize;
use solana_pubkey::Pubkey;

/// Each fleet's per-fleet crew aggregate cache — PDA `["FleetCrewBinding", fleet]`, one per
/// fleet (`state/crew/fleet_binding.rs`). Presence = at least one crew has ever onboarded via
/// `LoadFleetCrewRoster` (created-if-needed there; kept, never closed — an empty `summary`
/// already means vanilla). Every crew-decorated gameplay loop reads `summary` (the aggregate
/// of ONLY this fleet's onboarded crew) through its append-last `crew_binding` account, and
/// the pouring loops write the per-category XP accumulators back (hence WRITABLE there).
///
/// Sized Pod account — body 395 B (403 with the 8-byte account discriminator): the
/// `version` + `bump` + `_reserved[6]` + `fleet` + `owner_profile` header is 72 B, so
/// `summary` (315 B) begins at account offset 8 + 72 = 80, then `last_action_epoch` (8 B).
/// (The pre-#17 body was 346 B with the 274-byte summary and no epoch tail; both growths are
/// TAIL appends, so every pre-tail offset is unchanged.)

#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Debug, Clone, borsh::BorshSerialize, CarbonDeserialize, PartialEq)]
pub struct FleetCrewBinding {
    /// Data version of this account.
    pub version: u8,
    /// PDA bump.
    pub bump: u8,
    /// Reserved (zero today) — forward-compat slack.
    pub _reserved: [u8; 6],
    /// The fleet this cache belongs to (integrity check vs. the PDA seed).
    pub fleet: Pubkey,
    /// The owner profile — the owner-lock captured when the first crew onboards; gameplay
    /// resolves re-check this against the fleet's `owner_profile`.
    pub owner_profile: Pubkey,
    /// The per-fleet crew aggregate — the sum of ONLY the crew onboarded to this fleet
    /// (the identical 315-byte `RosterSummary` shape the whole roster uses).
    pub summary: RosterSummary,
    /// The fleet's last-acted withdraw-epoch (the `FirstActionPerEpoch` Cold Start marker;
    /// stamped by the warp resolve). Tail-appended after `summary`.
    pub last_action_epoch: u64,
}

impl FleetCrewBinding {
    pub fn decode(data: &[u8]) -> Option<Self> {
        if data.len() < 8 {
            return None;
        }
        let discriminator = &data[0..8];
        if discriminator != &[203, 64, 149, 37, 111, 204, 184, 181] {
            return None;
        }

        let data_slice = data;

        let data_slice = &data_slice[8..];

        Self::deserialize(data_slice)
    }
}
